package codeflow

import codeflow.graph.GraphException
import codeflow.java.AstReader
import com.google.gson.JsonObject
import com.google.gson.JsonParser
import org.w3c.dom.Document
import org.w3c.dom.Element
import java.io.ByteArrayInputStream
import java.nio.file.Files
import java.nio.file.Path
import javax.xml.parsers.DocumentBuilderFactory
import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertFailsWith
import kotlin.test.assertTrue


class AppTest {

    private val userDirectory = System.getProperty("user.dir")
    private val userDirPath = Path.of(userDirectory)
    private val testResourcesPath = userDirPath
        .resolve("src")
        .resolve("test")
        .resolve("resources")

    private fun buildGraph(testDir: String, testFiles: List<String>, from: String? = null): List<String> {
        val testDirPath = testResourcesPath.resolve(testDir)
        val testFilePaths = testFiles.map { testDirPath.resolve(it) }
        val mainMethod = AstReader(testResourcesPath).process(testFilePaths, from)

        val result = ArrayList<String>()
        MermaidExporter()
            .processMainMethod(mainMethod) { result.add(it) }
        return result
    }

    /**
     * The GraphML rendering, parsed.
     *
     * Parsing with a real XML parser rather than matching text is the point: a label that is XML
     * syntax has to come back out as its own characters, and the document has to be something a
     * viewer can actually open.
     */
    private fun buildGraphml(testDir: String, testFiles: List<String>): Document {
        val testDirPath = testResourcesPath.resolve(testDir)
        val testFilePaths = testFiles.map { testDirPath.resolve(it) }
        val mainMethod = AstReader(testResourcesPath).process(testFilePaths)

        val text = StringBuilder()
        GraphmlExporter()
            .processMainMethod(mainMethod) { text.append(it).append("\n") }
        return DocumentBuilderFactory.newInstance()
            .newDocumentBuilder()
            .parse(ByteArrayInputStream(text.toString().toByteArray()))
    }

    /** The JSON rendering, parsed with a library that did not write it. */
    private fun buildJson(testDir: String, testFiles: List<String>): JsonObject {
        val testDirPath = testResourcesPath.resolve(testDir)
        val testFilePaths = testFiles.map { testDirPath.resolve(it) }
        val mainMethod = AstReader(testResourcesPath).process(testFilePaths)

        val text = StringBuilder()
        JsonExporter().processMainMethod(mainMethod) { text.append(it).append("\n") }
        return JsonParser.parseString(text.toString()).asJsonObject
    }

    private fun jsonNodes(doc: JsonObject) = doc.getAsJsonArray("nodes").map { it.asJsonObject }

    private fun jsonLabel(node: JsonObject) = node.get("label").asString

    private fun jsonParent(node: JsonObject) = node.get("parent")?.asString

    private fun jsonSource(node: JsonObject) = node.get("source")?.asString

    /** The JSON edges as (source label, target label) pairs, to compare against [edgeLabels]. */
    private fun jsonEdgeLabels(doc: JsonObject): List<Pair<String, String>> {
        val labels = jsonNodes(doc).associate { it.get("id").asString to jsonLabel(it) }
        return doc.getAsJsonArray("edges").map { it.asJsonObject }.map {
            (labels[it.get("source").asString] ?: "?") to (labels[it.get("target").asString] ?: "?")
        }
    }

    private fun elements(doc: Document, tag: String): List<Element> {
        val found = doc.getElementsByTagName(tag)
        return (0 until found.length).map { found.item(it) as Element }
    }

    /** A node's own `data`, not that of the nodes nested inside it. */
    private fun dataOf(node: Element, key: String): String? {
        val children = node.childNodes
        return (0 until children.length)
            .mapNotNull { children.item(it) as? Element }
            .firstOrNull { it.tagName == "data" && it.getAttribute("key") == key }
            ?.textContent
    }

    private fun labelOf(node: Element) = dataOf(node, "label") ?: ""

    /** The label of the block this node is nested in, or null for the outermost one. */
    private fun enclosingBlockLabel(node: Element): String? {
        var ancestor = node.parentNode
        while (ancestor != null) {
            if (ancestor is Element && ancestor.tagName == "node") return labelOf(ancestor)
            ancestor = ancestor.parentNode
        }
        return null
    }

    /** The GraphML edges as (source label, target label) pairs, to compare against [edgeLabels]. */
    private fun graphmlEdgeLabels(doc: Document): List<Pair<String, String>> {
        val labels = elements(doc, "node").associate { it.getAttribute("id") to labelOf(it) }
        return elements(doc, "edge").map {
            (labels[it.getAttribute("source")] ?: "?") to (labels[it.getAttribute("target")] ?: "?")
        }
    }

    /** The declared nodes as (label, type) pairs, ignoring the generated ids. */
    private fun nodeTypes(graph: List<String>): List<Pair<String, String>> {
        val declaration = Regex("""^\s*n\d+\[([^]]*)]:::(\w+)$""")
        return graph.mapNotNull { line ->
            declaration.find(line)?.let { it.groupValues[1] to it.groupValues[2] }
        }
    }

    /** The graph's edges as (source label, target label) pairs, ignoring the generated ids. */
    private fun edgeLabels(graph: List<String>): List<Pair<String, String>> {
        val edge = Regex("""n\d+\[([^]]*)]:::\w+ --> n\d+\[([^]]*)]""")
        return graph.mapNotNull { line ->
            edge.find(line)?.let { it.groupValues[1] to it.groupValues[2] }
        }
    }

    /**
     * Whether a value can reach another node by following edges.
     *
     * Labels alone cannot answer this when two distinct variables share a name, which is exactly
     * the case worth testing, so this walks the ids and only uses labels for the two endpoints.
     */
    private fun reaches(graph: List<String>, fromLabel: String, toLabel: String): Boolean {
        val edge = Regex("""(n\d+)\[([^]]*)]:::\w+ --> (n\d+)\[([^]]*)]""")
        val edges = graph.mapNotNull { edge.find(it) }
        val outgoing = edges.groupBy({ it.groupValues[1] }, { it.groupValues[3] })
        val labelOf = HashMap<String, String>()
        edges.forEach {
            labelOf[it.groupValues[1]] = it.groupValues[2]
            labelOf[it.groupValues[3]] = it.groupValues[4]
        }
        val seen = HashSet<String>()
        val queue = ArrayDeque(labelOf.filterValues { it == fromLabel }.keys)
        while (queue.isNotEmpty()) {
            val id = queue.removeFirst()
            if (!seen.add(id)) continue
            if (labelOf[id] == toLabel && seen.size > 1) return true
            outgoing[id]?.forEach { queue.addLast(it) }
        }
        return false
    }

    private fun codeflow(testDir: String, testFiles: List<String>) {
        val testDirPath = testResourcesPath.resolve(testDir)
        val result = buildGraph(testDir, testFiles)

        // The snapshot is only written when it does not exist yet, or when explicitly asked for.
        // Rewriting it on every mismatch would let a regression overwrite the expectation and pass
        // on the next run.
        val truthPath = testDirPath.resolve("truth.md")
        if (!Files.exists(truthPath) || System.getenv("UPDATE_SNAPSHOTS") == "1") {
            Files.write(truthPath, result)
        }
        assertEquals(
            Files.readAllLines(truthPath), result,
            "Graph for '$testDir' does not match truth.md. Re-run with UPDATE_SNAPSHOTS=1 to accept the new output."
        )

        assertNoSelfEdges(testDir, result)
        assertNoUnknownOperators(testDir, result)
        assertNoDuplicateNodeIds(testDir, result)
    }

    /**
     * A node with an edge to itself means two different AST nodes were given the same id and so
     * were merged into one. Nothing in the language produces a value that flows into itself.
     */
    private fun assertNoSelfEdges(testDir: String, graph: List<String>) {
        val edge = Regex("""n(\d+)\[[^]]*]:::\w+ --> n(\d+)\[""")
        val selfEdges = graph.filter { line ->
            val match = edge.find(line)
            match != null && match.groupValues[1] == match.groupValues[2]
        }
        assertTrue(selfEdges.isEmpty(), "Graph for '$testDir' has nodes with an edge to themselves: $selfEdges")
    }

    /**
     * Two nodes rendered under one id are drawn as one box, and every edge of both lands on it, so
     * the diagram claims values flow between things that never touched. Identity used to be a hash
     * of the node's label and call stack, which could always collide; it is now a serial handed out
     * at creation, which cannot. This is here to notice if a derived id is ever reintroduced.
     *
     * Only the declaration lines are checked. The exporter repeats a node's full string on every
     * edge line it appears in, which is not a duplicate declaration.
     */
    private fun assertNoDuplicateNodeIds(testDir: String, graph: List<String>) {
        val declaration = Regex("""^\s*(n\d+)\[[^]]*]:::\w+$""")
        val ids = graph.mapNotNull { declaration.find(it)?.groupValues?.get(1) }
        val duplicates = ids.groupBy { it }.filterValues { it.size > 1 }.keys
        assertTrue(duplicates.isEmpty(), "Graph for '$testDir' declares the same node id twice: $duplicates")
    }

    /** An unlabelled operator makes the graph of a calculation unreadable. */
    private fun assertNoUnknownOperators(testDir: String, graph: List<String>) {
        val unknown = graph.filter { it.contains("[UNKNOWN]") }
        assertTrue(unknown.isEmpty(), "Graph for '$testDir' has unlabelled operators: $unknown")
    }

    /**
     * Both branches of `cond ? a : b` produce the value of the expression and the condition picks
     * between them, so all three have to reach the result. Anything less silently drops a value
     * that the code really can produce: for a guarded division it hides either the guard or the
     * fallback.
     */
    @Test
    fun ternaryConnectsBothBranchesAndCondition() {
        val edges = edgeLabels(buildGraph("ternary", listOf("App.java")))
        assertTrue("==" to "ternary" in edges, "condition does not reach the selection: $edges")
        assertTrue("fallback" to "ternary" in edges, "true branch does not reach the selection: $edges")
        assertTrue("div" to "ternary" in edges, "false branch does not reach the selection: $edges")
        assertTrue("ternary" to "guarded" in edges, "selection does not reach the variable: $edges")
    }

    /**
     * A value written in one branch of an `if` and one written before it both reach a use below it.
     *
     * `if (b == 7) { b = 13; } else { a = 17; }` leaves `c = b` able to hold 5 or 13 and `d = a` able
     * to hold 5 or 17, and the diagram used to claim each could hold only one - the value from
     * whichever branch was walked last. That is the failure this project is arranged around: not an
     * error, not a gap, a complete-looking graph asserting a flow the program does not have and
     * missing one it does.
     *
     * Asked with [reaches] rather than on adjacent edges because the join is a box of its own: `13`
     * arrives at `c` through the phi for `b`, which is the point.
     */
    @Test
    fun bothPathsOfABranchReachAUseAfterIt() {
        val graph = buildGraph("if1", listOf("App.java"))
        assertTrue(reaches(graph, "13", "c"), "the value written in the branch does not reach 'c'")
        assertTrue(reaches(graph, "5", "c"), "the value written before the branch does not reach 'c'")
        assertTrue(reaches(graph, "17", "d"), "the value written in the branch does not reach 'd'")
        assertTrue(reaches(graph, "5", "d"), "the value written before the branch does not reach 'd'")
    }

    /**
     * A loop body runs some number of times including none, and every count has to be on the page.
     *
     * `int y = 0; for (...) { y = 7; } int z = y;` gives `z` either 0 or 7, and the loop was drawn
     * straight through - `z` took the 7 and nothing else, which reads as "this loop always runs".
     * The counter had the mirror problem: `i++` produced a box with no edge leaving it, so the
     * value the condition tests on every iteration but the first came from nowhere.
     */
    @Test
    fun aValueFromBeforeALoopAndOneFromInsideItBothReachAUseAfterIt() {
        val graph = buildGraph("forLoop", listOf("App.java"))
        assertTrue(reaches(graph, "7", "z"), "the value written in the loop does not reach 'z'")
        assertTrue(reaches(graph, "0", "z"), "the value from before the loop does not reach 'z'")
        assertTrue(reaches(graph, "postInc", "<"), "the incremented counter is never tested again")
    }

    /**
     * `counter++` moves the variable on, so the next read of it is of the incremented value.
     *
     * The operator had a box and the box had no consequence: `counter++; int after = counter;` drew
     * `after` taking the value from before the increment, which is a plain arithmetic error sitting
     * in a diagram that otherwise looks right.
     */
    @Test
    fun anIncrementIsTheValueTheVariableHoldsAfterIt() {
        val edges = edgeLabels(buildGraph("unary", listOf("App.java")))
        assertTrue("postInc" to "afterIncrement" in edges, "the increment does not reach the read after it: $edges")
    }

    /**
     * Every arm of a `switch` statement reaches a use below it, and so does falling between them.
     *
     * The fixture's arms are deliberately uneven - one writes a second variable and falls into the
     * next, the default writes both - so that walking them as if they ran in sequence shows up.
     * That is what happened: `out = chosen + side` took the default's 100 and 500 and nothing else,
     * which is a diagram of a `switch` claiming the last arm always runs.
     *
     * `side` is the one that needs the fall-through. `case 3:` is reached either directly, with
     * `side` still 200, or out of the bottom of `case 2:`, which set it to 300, so both have to be
     * there - and a join that took only the falling path would drop the 200 with nothing to show
     * for it.
     */
    @Test
    fun everyArmOfASwitchStatementReachesAUseBelowIt() {
        val graph = buildGraph("switchStatement", listOf("App.java"))
        listOf("10", "30", "100").forEach {
            assertTrue(reaches(graph, it, "out"), "the arm writing $it does not reach 'out'")
        }
        listOf("200", "300", "500").forEach {
            assertTrue(reaches(graph, it, "out"), "the value $it of 'side' does not reach 'out'")
        }
    }

    /**
     * A call to a method outside the analysed sources has no body to inline, so it becomes one
     * node that the arguments flow into and the result flows out of. Values still have to be
     * traceable through it.
     */
    @Test
    fun externalCallBecomesOpaqueNode() {
        val edges = edgeLabels(buildGraph("externalCall", listOf("App.java")))
        assertTrue("a" to "abs" in edges, "argument does not reach the external call: $edges")
        assertTrue("abs" to "b" in edges, "external call result does not reach the variable: $edges")
        assertTrue("b" to "println" in edges, "argument does not reach the external call: $edges")
        assertTrue("+" to "c" in edges, "flow does not continue past the external call: $edges")
    }

    /**
     * An object returned by a method outside the analysed sources has no constructor to run, so
     * nothing is known about its memory position. It still has to be usable as a receiver.
     */
    @Test
    fun externalObjectIsUsableAsReceiver() {
        val edges = edgeLabels(buildGraph("externalObject", listOf("App.java")))
        assertTrue("of" to "items" in edges, "external call result does not reach the variable: $edges")
        assertTrue("items" to "size" in edges, "receiver does not reach the call made on it: $edges")
        assertTrue("+" to "doubled" in edges, "flow does not continue past the external object: $edges")
    }

    /** The receiver of a call can be another call, so a value has to stay traceable along a chain. */
    @Test
    fun chainedCallsStayConnected() {
        val edges = edgeLabels(buildGraph("chainedCall", listOf("App.java")))
        assertTrue("items" to "stream" in edges, "receiver does not reach the first call: $edges")
        assertTrue("stream" to "toList" in edges, "first call does not reach the second: $edges")
        assertTrue("toList" to "size" in edges, "second call does not reach the third: $edges")
        assertTrue("size" to "size" in edges, "call result does not reach the variable: $edges")
    }

    /**
     * A unary operator has to become a node of its own. Returning the operand's node instead
     * makes `-value` identical to `value` and `!flag` identical to `flag`, which is not a gap in
     * the graph but a claim that the code does something it does not.
     */
    @Test
    fun unaryOperatorsAreVisibleInTheGraph() {
        val edges = edgeLabels(buildGraph("unary", listOf("App.java")))
        assertTrue("value" to "neg" in edges, "operand does not reach the negation: $edges")
        assertTrue("neg" to "negated" in edges, "negation does not reach the variable: $edges")
        assertTrue("flag" to "not" in edges, "operand does not reach the complement: $edges")
        assertTrue("not" to "inverted" in edges, "complement does not reach the variable: $edges")
        assertTrue("counter" to "postInc" in edges, "operand does not reach the increment: $edges")
    }

    /**
     * An expression codeflow does not model becomes a node saying so, rather than ending the run.
     *
     * One `(int)` cast on a reachable path used to produce zero bytes of output for the entire
     * corpus: `Helper.twice` containing `(int)(v * 2.0)` took down a graph of which it was one node,
     * and a thousand other files went with it.
     *
     * The principle behind the gate is unchanged - a gap must never be drawn as a flow - but there
     * is already an honest rendering for "something here I cannot see inside", and a cast is not
     * more dangerous than `java.util`. So the construct is drawn, labelled with its kind and
     * carrying the line it was written on, with what it was built from flowing in and its value
     * flowing out. It is its own node type, so nothing on the diagram can mistake it for a value
     * codeflow understood.
     */
    @Test
    fun anUnmodelledExpressionBecomesANodeInsteadOfEndingTheRun() {
        val graph = buildGraph("unsupported", listOf("App.java"))
        val types = nodeTypes(graph)
        val edges = edgeLabels(graph)
        assertTrue("TYPE_CAST" to "UNMODELLED" in types, "the cast is not drawn as unmodelled: $types")
        assertTrue("3L" to "TYPE_CAST" in edges, "the operand does not reach the cast: $edges")
        assertTrue("TYPE_CAST" to "count" in edges, "the cast does not reach the variable: $edges")
    }

    /**
     * The same on the right-hand side of an object assignment.
     *
     * That path caught every exception from evaluating the right-hand side and carried on, so an
     * unmodelled construct there did not fail - the variable was simply drawn with nothing flowing
     * into it, which reads as a value that has no source rather than one codeflow could not follow.
     * Object assignment is most of real Java, so this was the gate's largest blind spot, and the
     * node has to arrive on this path rather than the edge being dropped again.
     */
    @Test
    fun anUnmodelledExpressionAssignedToAnObjectIsDrawnToo() {
        val graph = buildGraph("unsupportedAssignment", listOf("App.java"))
        val edges = edgeLabels(graph)
        assertTrue("args" to "TYPE_CAST" in edges, "the operand does not reach the cast: $edges")
        assertTrue("TYPE_CAST" to "cast" in edges, "the cast does not reach the variable: $edges")
    }

    /**
     * And for the receiver of a call reaching outside the sources.
     *
     * That receiver was evaluated inside a catch-everything that dropped whatever came back, so the
     * one position where the gate could be reached and ignored was the position it exists for. The
     * result was the opaque call drawn with no input at all: a call that plainly reads a value,
     * drawn as reading nothing.
     */
    @Test
    fun anUnmodelledReceiverStillReachesTheCall() {
        val graph = buildGraph("unmodelledReceiver", listOf("App.java"))
        val edges = edgeLabels(graph)
        assertTrue("args" to "TYPE_CAST" in edges, "the operand does not reach the cast: $edges")
        assertTrue("TYPE_CAST" to "toString" in edges, "the cast does not reach the call: $edges")
    }

    /**
     * The entry point can be named, instead of being whichever `main` sorts first.
     *
     * The whole diagram is what one method reaches, so which method that is *is* the diagram. Only
     * `main` could be it, which meant a reader interested in one service method had to find a path
     * to it from an entry point and then look for it among everything else the entry point reaches.
     */
    @Test
    fun theEntryPointCanBeNamedRatherThanBeingWhicheverMainSortsFirst() {
        val graph = buildGraph("funcCall", listOf("App.java"), from = "App#methodB")
        val labels = nodeTypes(graph).map { it.first }
        val edges = edgeLabels(graph)
        assertTrue(graph.any { it.contains("""subgraph b0["methodB"]""") }, "methodB is not the root: $graph")
        assertTrue("11" to "paramH" in edges, "the chosen method's own body is missing: $edges")
        assertTrue("x" !in labels, "main's body was graphed as well: $labels")
    }

    /**
     * And a corpus with no `main` at all is graphable, which is most Java.
     *
     * Services, controllers and libraries have no entry point of their own, so refusing to start
     * anywhere else excluded most of the tool's own subject matter - including Fineract, its stated
     * real-world target.
     */
    @Test
    fun aCorpusWithNoMainCanStillBeGraphed() {
        val edges = edgeLabels(buildGraph("noMain", listOf("Report.java"), from = "Report#total"))
        assertTrue("base" to "*" in edges, "the parameter does not reach the operator: $edges")
        assertTrue("*" to "bonus" in edges, "the operator does not reach the variable: $edges")
    }

    /**
     * Naming a method that is not there says so, and says what the alternatives were.
     *
     * A typo in a class or method name is the commonest way to get here, and an error that only
     * repeats the name back leaves the reader guessing at spelling, nesting and overloads.
     */
    @Test
    fun anEntryPointThatMatchesNothingNamesTheCandidates() {
        val error = assertFailsWith<GraphException> {
            buildGraph("funcCall", listOf("App.java"), from = "App#methodZ")
        }
        val message = error.message ?: ""
        assertTrue("App#methodZ" in message, "error does not repeat what was asked for: $message")
        assertTrue("App#methodB" in message, "error does not name a real candidate: $message")
    }

    /**
     * And no `main` with nothing asked for points at the flag rather than at a dead end.
     *
     * This was the whole failure: `No method named 'main'`, and nothing about what to do next.
     */
    @Test
    fun noMainAndNoChoiceSaysHowToChoose() {
        val error = assertFailsWith<GraphException> { buildGraph("noMain", listOf("Report.java")) }
        val message = error.message ?: ""
        assertTrue("--from" in message, "error does not name the flag: $message")
        assertTrue("Report#total" in message, "error does not name a candidate: $message")
    }

    /**
     * The run says what it could not model, so a reader is told rather than left to notice.
     *
     * The node on the diagram is not enough on its own: nobody opens a graph of a thousand nodes
     * looking for the handful that are gaps. This is also what the exit status is taken from, which
     * is the only part of it a build can act on.
     *
     * Once per construct, not once per call site. A method is inlined at every call, so one cast in
     * a helper called from twenty places would otherwise be reported twenty times - a count nobody
     * could reconcile with the source.
     */
    @Test
    fun theRunReportsEachConstructItCouldNotModelOnce() {
        val testDirPath = testResourcesPath.resolve("unsupported")
        val reader = AstReader(testResourcesPath)
        reader.process(listOf(testDirPath.resolve("App.java")))
        assertEquals(listOf("TYPE_CAST at unsupported/App.java:15:21"), reader.unmodelled)
    }

    /** And says nothing when there was nothing to say, so the summary means something. */
    @Test
    fun aRunThatModelledEverythingReportsNothing() {
        val testDirPath = testResourcesPath.resolve("base")
        val reader = AstReader(testResourcesPath)
        reader.process(listOf(testDirPath.resolve("App.java")))
        assertTrue(reader.unmodelled.isEmpty(), "reported a gap where there is none: ${reader.unmodelled}")
    }

    /**
     * The node carries the construct's own line, not the enclosing statement's.
     *
     * A reader who sees `TYPE_CAST` on the diagram has one question, and it is where to look. The
     * label alone names the kind, which on a file with several casts narrows nothing.
     */
    @Test
    fun anUnmodelledNodeSaysWhereTheConstructWas() {
        val cast = jsonNodes(buildJson("unsupported", listOf("App.java")))
            .single { it.get("type").asString == "UNMODELLED" }
        assertEquals("TYPE_CAST", jsonLabel(cast))
        assertTrue(
            jsonSource(cast)?.startsWith("unsupported/App.java:15:") == true,
            "the cast on line 15 does not say so: ${jsonSource(cast)}"
        )
    }

    /**
     * `new X(...)` is a value, and the variable it is assigned to has to receive it.
     *
     * It was not modelled as one: the constructor was inlined as a side effect of working out the
     * memory position, and nothing produced a node for the object. In an argument position that
     * failed outright; in an assignment position the failure was swallowed, so the variable was
     * simply drawn with nothing flowing into it and the diagram read as if the object came from
     * nowhere. That is on nearly every line of real Java.
     */
    @Test
    fun constructedObjectReachesTheVariableItIsAssignedTo() {
        val edges = edgeLabels(buildGraph("newObject", listOf("App.java")))
        assertTrue("seed" to "v" in edges, "argument does not reach the constructor parameter: $edges")
        assertTrue("<init>" to "box" in edges, "the constructed object does not reach the variable: $edges")
        assertTrue("\"text\"" to "StringBuilder" in edges, "argument does not reach the opaque construction: $edges")
        assertTrue("StringBuilder" to "sb" in edges, "the opaque construction does not reach the variable: $edges")
    }

    /**
     * A method on a nested class is code in the analysed sources and has to be inlined like any
     * other. Only the top level was walked, so every nested and inner class came out as the opaque
     * external node - a box labelled with the method name and nothing inside it, indistinguishable
     * on the diagram from a call into the standard library.
     */
    @Test
    fun aMethodOnANestedClassIsInlinedLikeAnyOther() {
        val edges = edgeLabels(buildGraph("nestedClass", listOf("App.java")))
        assertTrue("seed" to "v" in edges, "argument does not reach the parameter: $edges")
        assertTrue("v" to "+" in edges, "the nested class's body was not inlined: $edges")
        assertTrue("+" to "twice" in edges, "the nested class's body does not reach its return: $edges")
        assertTrue("twice" to "doubled" in edges, "the return does not reach the variable: $edges")
    }

    /**
     * `this` passed as an argument is a value like any other, and it is the object the method is
     * running on - so what the callee reads off it has to be that object's fields.
     *
     * It had no node at all: `this` was handled when working out a memory position but not when
     * evaluating, so a bare `this` was a name that resolved to nothing and took the method down.
     * A builder handing itself to a constructor is the ordinary case.
     */
    @Test
    fun thisIsAValueCarryingTheObjectItRefersTo() {
        val graph = buildGraph("thisReference", listOf("App.java"))
        val edges = edgeLabels(graph)
        assertTrue("this" to "origin" in edges, "`this` does not reach the parameter it is passed to: $edges")
        assertTrue("value" to "held" in edges, "the field read through `this` is not the object's own: $edges")
        assertTrue(reaches(graph, "7", "out"), "the value does not survive the round trip through `this`: $graph")
    }

    /**
     * An object passed to a method is the same object inside it, so a field read off the parameter
     * has to find the field the caller's object holds.
     *
     * Only the nodes were connected, never the memory positions, so the parameter named an object
     * nothing was known about and `origin.value` took the opaque path: a node labelled `value`,
     * of the type that means "outside the analysed sources", with no edge to the field really
     * holding the value. The diagram was complete and readable and the flow it drew was false.
     */
    @Test
    fun anObjectArgumentIsTheSameObjectInsideTheMethod() {
        val graph = buildGraph("objectArgument", listOf("App.java"))
        val edges = edgeLabels(graph)
        assertTrue("seed" to "value" in edges, "the constructor does not fill the field: $edges")
        assertTrue("value" to "read" in edges, "the field read off the parameter is not the object's own: $edges")
        assertTrue(reaches(graph, "7", "out"), "the value does not survive being passed as an object: $graph")
    }

    /**
     * The object a factory method returns is the object it constructed, so a method inlined on it
     * afterwards reads that object's fields.
     *
     * The result of a call was given a memory position of its own, holding nothing. That is not a
     * harmless approximation: inlining a method against it means the body's own field reads resolve
     * to nothing, so `Money.of(...)` followed by `.getAmount()` - a factory then a getter, which is
     * most of a real codebase - took the whole run down.
     */
    @Test
    fun theObjectAMethodReturnsKeepsItsIdentity() {
        val graph = buildGraph("returnedObject", listOf("App.java"))
        val edges = edgeLabels(graph)
        assertTrue("seed" to "held" in edges, "the constructor does not fill the field: $edges")
        assertTrue("held" to "read" in edges, "the getter does not read the constructed object's field: $edges")
        assertTrue(reaches(graph, "3", "out"), "the value does not survive the factory and the getter: $graph")
    }

    /**
     * Every argument past the last declared parameter flows into the varargs one.
     *
     * They all end up in the array it names, so they all reach it. Indexing straight into the
     * parameter list walked off the end instead, and an IndexOutOfBoundsException names no source
     * at all - `String.format(fmt, x, y)` against an in-source method is enough to reach it.
     */
    @Test
    fun everyArgumentPastTheLastParameterReachesTheVarargsOne() {
        val graph = buildGraph("varargs", listOf("App.java"))
        val edges = edgeLabels(graph)
        assertTrue("1" to "base" in edges, "the fixed argument does not reach its parameter: $edges")
        assertTrue("2" to "rest" in edges, "the first variadic argument does not reach the array: $edges")
        assertTrue("3" to "rest" in edges, "the second variadic argument does not reach the array: $edges")
        assertTrue(reaches(graph, "3", "out"), "a variadic value does not survive the call: $graph")
    }

    /**
     * A bare `return;` carries no value, and does not stop the rest of the method being graphed.
     *
     * Every return was assumed to have a value, so an early exit - the ordinary guard clause at the
     * top of a method - came out as a NullPointerException with no file and no line. That is worse
     * to be handed than a wrong graph: there is nothing in it to look at.
     */
    @Test
    fun aReturnWithNoValueCarriesNone() {
        val graph = buildGraph("voidReturn", listOf("App.java"))
        val edges = edgeLabels(graph)
        assertTrue("seed" to "held" in edges, "the method past the early exit was not graphed: $edges")
        assertTrue(reaches(graph, "5", "out"), "the value does not survive the call: $graph")
        assertTrue(edges.none { it.second == "store" }, "the valueless return was wired up: $edges")
    }

    /**
     * `names::size` is a value, and the object it is bound to flows into it.
     *
     * Nothing here calls it, so the method it names has no arguments to bind and no call site to be
     * inlined under - it is opaque, like a call outside the sources. What it captures is not: the
     * receiver is a real value the function holds on to, and dropping that edge would break the
     * chain through every stream pipeline in a modern codebase.
     */
    @Test
    fun aMethodReferenceIsAValueCarryingWhatItCaptures() {
        val graph = buildGraph("memberReference", listOf("App.java"))
        val edges = edgeLabels(graph)
        assertTrue("names" to "size" in edges, "the captured receiver does not reach the reference: $edges")
        assertTrue("size" to "counter" in edges, "the reference does not reach the variable: $edges")
        assertTrue("size" to "EXTERNAL" in nodeTypes(graph), "the reference is not opaque: ${nodeTypes(graph)}")
    }

    /**
     * A call through an interface is opaque; a call to a class that has the body inlines it.
     *
     * The declaration with no body was registered as if it had one, so reaching it was a
     * NullPointerException with no file or line - the one failure mode worse than a wrong graph,
     * because it names nothing to look at. It is left unregistered instead: which implementation a
     * call reaches is decided by the receiver's run-time class, and picking one would be a guess
     * drawn as fact.
     */
    @Test
    fun aCallThroughAnInterfaceIsOpaqueAndACallWithABodyIsNot() {
        val graph = buildGraph("abstractMethod", listOf("App.java"))
        val edges = edgeLabels(graph)
        val types = nodeTypes(graph)
        assertTrue("read" to "EXTERNAL" in types, "the interface call is not opaque: $types")
        assertTrue("read" to "RETURN" in types, "the direct call was not inlined: $types")
        assertTrue("read" to "viaInterface" in edges, "the opaque call produces no value: $edges")
        assertTrue("seed" to "+" in edges, "the body reached through the class is not inlined: $edges")
        assertTrue(reaches(graph, "4", "viaClass"), "the value does not survive the direct call: $graph")
    }

    /**
     * A node says where in the source it came from.
     *
     * "Which line is this?" is the question a reader of unfamiliar code asks constantly, and nothing
     * carried a position past the builder, so no exporter and no viewer could answer it. codemap
     * tags every node with its line and asserts it in the goldens; this is that, arrived at from the
     * other direction.
     *
     * The line is pinned and the column is not. The line is the behaviour - it is what a reader
     * navigates by - and the column moves whenever the fixture is reindented, which would make this
     * fail for a reason that has nothing to do with what it tests.
     */
    @Test
    fun aNodeCarriesTheSourceLineItWasWrittenOn() {
        val nodes = jsonNodes(buildJson("base", listOf("App.java")))
        val literal = nodes.single { jsonLabel(it) == "5" }
        val source = jsonSource(literal)
        assertTrue(
            source != null && source.startsWith("base/App.java:8:"),
            "the literal on line 8 does not say so: $source"
        )
    }

    /**
     * Every node, not merely the ones that were easy.
     *
     * A position on most nodes is worse than none on any: the viewer would offer to navigate and
     * silently do nothing on whichever kinds were missed, and which kinds those are is invisible
     * from the outside. Every node has a declaration or an expression to point at - a RETURN node
     * and a parameter have the method's, and a METHOD box is a declaration itself - so there is no
     * node in the graph with nothing honest to say.
     *
     * `funcCall` is the fixture because it has calls nested three deep, so a callee's nodes are
     * built while the *caller's* context is the one in hand. Taking that one would name the wrong
     * file as soon as a call crosses one, which no single-file fixture can show.
     */
    @Test
    fun everyNodeCarriesASource() {
        val nodes = jsonNodes(buildJson("funcCall", listOf("App.java")))
        val missing = nodes.filter { jsonSource(it).isNullOrBlank() }.map { jsonLabel(it) }
        assertTrue(missing.isEmpty(), "nodes with no source position: $missing")
    }

    /**
     * A method that calls itself is inlined once, and the call inside it is opaque.
     *
     * Inlining happens per call site with no in-progress set, so a recursive method had nothing
     * stopping it: `fact` took the run down with a StackOverflowError, no output at all, and a stack
     * trace naming the graph builder rather than a line of Java. A five-line factorial reaches it.
     *
     * The opaque node is the same answer a call outside the analysed sources gets, and it is honest
     * about what happened - a call whose body was not inlined any further, arguments in, result out.
     * The decision was recorded in `plan-for-these-improvements-mighty-prism.md` before this was
     * written, so it is settled rather than invented here.
     *
     * The outer call is still inlined, which is what distinguishes this from giving up on recursion
     * entirely: `seed` reaches the parameter, and only the second entry into `fact` is cut.
     */
    @Test
    fun aRecursiveCallIsOpaqueAndTheOuterCallIsStillInlined() {
        val graph = buildGraph("recursion", listOf("App.java"))
        val edges = edgeLabels(graph)
        assertTrue("fact" to "EXTERNAL" in nodeTypes(graph), "the recursive call is not opaque: ${nodeTypes(graph)}")
        assertTrue("seed" to "n" in edges, "the outer call was not inlined: $edges")
        assertTrue("-" to "fact" in edges, "the argument does not reach the recursive call: $edges")
        assertTrue("fact" to "*" in edges, "the recursive call's result does not flow out: $edges")
    }

    /**
     * The variable of an enhanced `for` is bound to what is being iterated, and the body can read it.
     *
     * Nothing bound it before, so every read in the body found no node and took the run down - and
     * the gate in `scan` covers expressions only, so the failure named a missing identifier several
     * lines from the loop that should have declared it, rather than naming the loop.
     */
    @Test
    fun theVariableOfAnEnhancedForIsBoundToWhatIsIterated() {
        val graph = buildGraph("enhancedFor", listOf("App.java"))
        val edges = edgeLabels(graph)
        assertTrue("names" to "name" in edges, "the collection does not reach the loop variable: $edges")
        assertTrue("name" to "length" in edges, "the loop variable does not reach the body: $edges")
        assertTrue(reaches(graph, "names", "total"), "the elements do not reach what the body computes: $graph")
    }

    /**
     * An enum constant is a value whichever way it is written.
     *
     * `Size.SMALL` was already a value with nothing flowing into it - the declaration is the value,
     * so there is no assignment to find. A bare `LARGE` inside the enum is the same thing written
     * shorter, and used to be a hard failure instead: `case 1 -> FLAT` in a `fromInt` switch, which
     * is on nearly every enum in a real codebase.
     */
    @Test
    fun anEnumConstantIsAValueBareOrQualified() {
        val graph = buildGraph("enumConstant", listOf("App.java"))
        val edges = edgeLabels(graph)
        assertTrue("LARGE" to "ternary" in edges, "the bare constant does not reach the selection: $edges")
        assertTrue("SMALL" to "ternary" in edges, "the qualified constant does not reach the selection: $edges")
        assertTrue(
            edges.none { it.second == "LARGE" || it.second == "SMALL" },
            "a constant is drawn with something flowing into it: $edges"
        )
    }

    /**
     * A lambda's body is drawn, and what it captures flows through it.
     *
     * Failing on every lambda stopped codeflow dead on most modern Java, and drawing it as one
     * opaque box would hide source the reader can see - the same black box the nested-class defect
     * produced. The body is walked in the enclosing block because nothing here calls the lambda, so
     * there is no call site to nest it under.
     */
    @Test
    fun aLambdaBodyIsDrawnAndWhatItCapturesFlowsThrough() {
        val graph = buildGraph("lambda", listOf("App.java"))
        val edges = edgeLabels(graph)
        assertTrue("base" to "*" in edges, "the captured value does not reach the body: $edges")
        assertTrue("*" to "lambda" in edges, "the body does not reach the function value: $edges")
        assertTrue(reaches(graph, "3", "lambda"), "the captured value does not survive the lambda: $graph")
    }

    /**
     * A lambda with a statement body returns to the lambda, not to the method around it.
     *
     * Its body is walked in the enclosing method's block, so a `return` inside it would otherwise
     * be wired to that method's return node - an edge asserting `main` returns a value it does not,
     * which is exactly the plausible-and-wrong diagram the gate exists to prevent.
     */
    @Test
    fun aStatementBodiedLambdaReturnsToItselfNotToTheMethodAroundIt() {
        val graph = buildGraph("statementLambda", listOf("App.java"))
        val edges = edgeLabels(graph)
        assertTrue("+" to "lambda" in edges, "the body does not reach the function value: $edges")
        assertTrue(edges.none { it.second == "main" }, "the lambda returns into the enclosing method: $edges")
    }

    /**
     * A field read before anything assigns it is a value with nothing flowing into it, and does not
     * stop the fields around it being tracked.
     *
     * This used to be a hard failure, on the grounds that a tracked object should know its own
     * fields. It should not: a builder left half-filled and then copied field by field is the usual
     * shape of real code, and `builder.neverSet` there is Java's default rather than something the
     * analysis lost. Taking the run down over it stopped every diagram containing one.
     */
    @Test
    fun aFieldReadBeforeItIsAssignedIsAValueRatherThanAFailure() {
        val graph = buildGraph("unassignedField", listOf("App.java"))
        val edges = edgeLabels(graph)
        assertTrue("neverSet" to "fromNeverSet" in edges, "the unassigned field does not reach the copy: $edges")
        assertTrue(
            edges.none { it.second == "neverSet" },
            "the unassigned field is drawn with something flowing into it: $edges"
        )
        assertTrue(reaches(graph, "4", "out"), "the assigned field alongside it lost its value: $graph")
    }

    /**
     * A local with no value is still a failure, and says where.
     *
     * This is the other half of [aFieldReadBeforeItIsAssignedIsAValueRatherThanAFailure]: a local
     * cannot be read before it is written, so not finding one means either the analysis lost it or
     * the program never wrote it. Letting every missing name through as a value from nowhere would
     * turn the loud failure into a plausible diagram, which is the trade this project refuses to
     * make.
     *
     * The fixture is one the compiler rejects, which codeflow still has to have an answer for:
     * attribution runs on sources that do not compile, since a tool pointed at a directory nobody
     * has read cannot require it to build. It replaced `unboundLocal`, whose gap was in codeflow and
     * has since been closed - see [codeflow.ir.IrGraphBuilderTest.aPatternOnASwitchStatementBindsItsName].
     */
    @Test
    fun aLocalWithNoValueStillFails() {
        val thrown = assertFailsWith<GraphException> {
            buildGraph("unwrittenLocal", listOf("App.java"))
        }
        assertTrue(
            thrown.message!!.contains("unwrittenLocal/App.java:19"),
            "the failure does not say which line: ${thrown.message}"
        )
    }

    /**
     * `SMALL(3)` runs a constructor, so the value written into the constant is the one its getter
     * returns - and each constant is its own object.
     *
     * Nothing ran the declaration, so `Size.SMALL` was opaque and `units()` was inlined against an
     * object with no fields: it returned a `units` with nothing flowing into it. That is a getter
     * drawn as producing a value from nowhere, on the shape most enums in real code have.
     *
     * The negative assertion is what says the constants are two objects rather than one; it is
     * paired with the two positives, which fail if nothing is connected at all.
     *
     * Ported from codemap's `enum` fixture. The bare form, where the declaration is the whole
     * value, stays as it was - see [anEnumConstantIsAValueBareOrQualified].
     */
    @Test
    fun anEnumConstantsConstructorArgumentReachesItsGetter() {
        val graph = buildGraph("enumConstructor", listOf("App.java"))
        assertTrue("units" to "VARIABLE" in nodeTypes(graph), "the constant's field is not tracked: ${nodeTypes(graph)}")
        assertTrue(reaches(graph, "3", "small"), "the first constant's argument does not reach its getter: $graph")
        assertTrue(reaches(graph, "9", "large"), "the second constant's argument does not reach its getter: $graph")
        assertTrue(!reaches(graph, "3", "large"), "the two constants share one object: $graph")
    }

    /**
     * A field initializer and an instance initializer block run as part of construction, so what
     * they assign is what the constructor reads and what the caller finds afterwards.
     *
     * Nothing outside a method body was ever walked. `counted = counted + add` therefore read a
     * `counted` with nothing flowing into it, `blocked` came back as a field nobody had assigned,
     * and `nested` named an object that had never been constructed, so `outer.nested.held` was an
     * opaque dead end. All three are complete, readable drawings of flows that are not the code's.
     *
     * `Plain` declares no constructor, so there is no body to inline and no box to draw - the
     * initializer still runs. The `add` assertion is what says the initializer did not simply
     * replace what the constructor does.
     *
     * Ported from codemap's `constructor_chain` fixture.
     */
    @Test
    fun fieldInitializersAndInstanceBlocksRunAsPartOfConstruction() {
        val graph = buildGraph("fieldInitializer", listOf("App.java"))
        assertTrue(reaches(graph, "5", "fromField"), "the field initializer did not run: $graph")
        assertTrue(reaches(graph, "3", "fromField"), "the constructor's own write was lost: $graph")
        assertTrue(reaches(graph, "7", "fromBlock"), "the instance initializer block did not run: $graph")
        assertTrue(reaches(graph, "10", "fromNested"), "an object built by a field initializer is not tracked: $graph")
        assertTrue(reaches(graph, "4", "fromPlain"), "a class with no written constructor skipped its initializer: $graph")
        assertTrue(reaches(graph, "1", "fromDelegated"), "the delegating constructor's chain is broken: $graph")
        // Two `new Outer(...)`, so `counted = 5` runs twice. A third occurrence means the
        // constructor delegated to ran the initializers that its `this(...)` caller had already run.
        assertEquals(
            2, nodeTypes(graph).count { it == ("5" to "LITERAL") },
            "the field initializer is drawn once per construction: ${nodeTypes(graph)}"
        )
    }

    /**
     * A `switch` used as a statement compares its selector against every case label, and walks
     * every arm.
     *
     * The selector's read was invisible: `visitSwitchExpression` models the expression form, there
     * was no `visitSwitch`, and a *statement* is not covered by the gate in `scan`, so nothing said
     * so. The default scan reached the selector and produced its node, then drew no edge out of it,
     * which is a diagram where the value that decides the whole branch appears to be unused.
     *
     * The count is what makes this fail on a plausible-but-wrong implementation: comparing the
     * selector once, or once per arm including `default`, both draw a switch that reads its
     * selector. Three constant labels means three comparisons.
     *
     * Ported from codemap's `switch` fixture.
     */
    @Test
    fun aSwitchStatementComparesItsSelectorAgainstEveryLabel() {
        val graph = buildGraph("switchStatement", listOf("App.java"))
        val edges = edgeLabels(graph)
        assertEquals(
            3, edges.count { it == ("selector" to "==") },
            "the selector is not compared against each of the three constant labels: $edges"
        )
        assertTrue("1" to "==" in edges, "the first case label is not compared: $edges")
        assertTrue("2" to "==" in edges, "the second case label is not compared: $edges")
        assertTrue("3" to "==" in edges, "the third case label is not compared: $edges")
        assertTrue("10" to "chosen" in edges, "the first arm was not walked: $edges")
        assertTrue("300" to "side" in edges, "the fall-through arm was not walked: $edges")
        assertTrue("500" to "side" in edges, "the default arm was not walked: $edges")
        assertTrue(reaches(graph, "100", "out"), "the value the switch left behind does not reach the read: $graph")
    }

    /**
     * With several entry points, the one graphed is the first by source path, whichever order the
     * files arrive in.
     *
     * The whole diagram is whatever that one method reaches, and the choice used to come out of a
     * HashMap: on a corpus with three `main`s it picked one reaching a single file and drew that,
     * complete and plausible, as the codebase. Order-independence is the testable half of the fix;
     * the other half is that the run says on stderr which one it took and what it passed over.
     */
    @Test
    fun theEntryPointIsChosenTheSameWayWhateverOrderTheFilesArriveIn() {
        val alphaFirst = edgeLabels(buildGraph("twoMains", listOf("Alpha.java", "Zeta.java")))
        val zetaFirst = edgeLabels(buildGraph("twoMains", listOf("Zeta.java", "Alpha.java")))
        assertTrue("fromAlpha" to "+" in alphaFirst, "the first main by path was not the one graphed: $alphaFirst")
        assertEquals(alphaFirst, zetaFirst, "the file order decided which main was graphed")
    }

    /**
     * `args[position]` takes a value out of the array, and which one depends on the index, so both
     * flow into it. `[]` cannot be the label: square brackets delimit a node in Mermaid.
     */
    @Test
    fun arrayAccessIsAValueFromBothTheArrayAndTheIndex() {
        val edges = edgeLabels(buildGraph("arrayAccess", listOf("App.java")))
        assertTrue("args" to "index" in edges, "the array does not reach the access: $edges")
        assertTrue("position" to "index" in edges, "the index does not reach the access: $edges")
        assertTrue("index" to "picked" in edges, "the access does not reach the variable: $edges")
        assertTrue("picked" to "length" in edges, "flow does not continue past the access: $edges")
    }

    /**
     * `new int[size]` and `new int[] { seed, 9 }` are both values built out of what is written
     * inside them, so the size and the elements flow into the array.
     *
     * The size counts as much as an element does. It is not what the array holds, but it is what
     * decides how much of it there is, and an array drawn with nothing flowing in reads as a value
     * that came from nowhere - the same wrongness as any other dropped operand.
     */
    @Test
    fun anArrayIsBuiltFromItsSizeAndItsElements() {
        val graph = buildGraph("arrayCreation", listOf("App.java"))
        val edges = edgeLabels(graph)
        assertTrue("size" to "array" in edges, "the size does not reach the array: $edges")
        assertTrue("seed" to "array" in edges, "an element does not reach the array: $edges")
        assertTrue("array" to "sized" in edges, "the array does not reach the variable: $edges")
        assertTrue("array" to "filled" in edges, "the array does not reach the variable: $edges")
        assertTrue(reaches(graph, "seed", "out"), "flow does not continue past the array: $edges")
    }

    /**
     * `catch (NumberFormatException failure)` binds a name the handler then reads.
     *
     * Nothing flows into it. Which throw reached this handler is control flow, and codeflow models
     * none, so the honest drawing is a value with no source - the same answer a lambda parameter
     * gets. What it must not be is absent: the gate in `scan` only covers expressions, so an
     * unmodelled *statement* names nothing and surfaces further down as a read of a name that has
     * no node, taking the whole run out on a line that is not the one at fault.
     */
    @Test
    fun aCaughtExceptionIsAValueTheHandlerCanRead() {
        val graph = buildGraph("catchParameter", listOf("App.java"))
        val edges = edgeLabels(graph)
        assertTrue("failure" to "getMessage" in edges, "the caught exception is not read: $edges")
        assertTrue("getMessage" to "reason" in edges, "the read does not reach the variable: $edges")
        assertTrue(reaches(graph, "failure", "out"), "flow does not continue out of the handler: $edges")
    }

    /**
     * A call written with no receiver runs on the enclosing instance, so a field it writes is a
     * write to the object the outer call was made on, and the caller's read afterwards finds it.
     *
     * Only the receiver written at the call site was used, and an unqualified call has none, so the
     * callee was inlined with no owner and its write landed on nothing anyone could look up. One
     * level deep hid it - `gauge.record()` has a receiver - and two levels did not, so the caller's
     * read quietly kept the value from before the call. The negative assertion is what says the
     * write replaced rather than merely joined, and is paired with the positive above it.
     *
     * Ported from codemap's `deep_method` fixture.
     */
    @Test
    fun aFieldWrittenTwoCallsDeepReachesTheCaller() {
        val graph = buildGraph("deepField", listOf("App.java"))
        val edges = edgeLabels(graph)
        assertTrue("18" to "reading" in edges, "the innermost write is missing: $edges")
        assertTrue(reaches(graph, "18", "taken"), "the write two calls down does not reach the caller: $edges")
        assertTrue(!reaches(graph, "17", "taken"), "the value from before the call was not replaced: $edges")
    }

    /**
     * `x = x + 1` reads x before it writes it, so the operand is the value x held going in.
     *
     * The target used to be created first, which registered it as the current value of x under the
     * same key, so the x in the expression found the node about to be written. That draws a cycle -
     * `x -> + -> x` on one box - orphans the previous value, and cuts the literal that produced it
     * off from everything downstream. `x += 1` was always right, because it evaluates the variable
     * first, so the two spellings of one statement disagreed. The assertion is on all three forms
     * for that reason.
     *
     * Found while porting codemap's `static_member`, where `total = total + by` made the write
     * unreachable from the read that fed it.
     */
    @Test
    fun anAssignmentReadsTheValueTheVariableHeldGoingIn() {
        val graph = buildGraph("selfAssignment", listOf("App.java"))
        val edges = edgeLabels(graph)
        assertTrue(reaches(graph, "1", "expanded"), "the previous value is orphaned by `x = x + n`: $edges")
        assertTrue(reaches(graph, "10", "expanded"), "the added value does not reach the result: $edges")
        assertTrue(reaches(graph, "2", "compound"), "the previous value is orphaned by `x += n`: $edges")
        assertTrue(reaches(graph, "3", "field"), "the previous value of a field is orphaned: $edges")
        assertTrue(reaches(graph, "30", "field"), "the added value does not reach the field: $edges")
    }

    /**
     * `Counter.total` and a bare `total` inside `Counter` are one variable, so a write through
     * either form has to be found by a read through the other.
     *
     * A static has no instance, so the MemPos that carries an instance field is not available, and
     * the block-parent chain is the wrong shape to fall back on: `bump`'s block is a *child* of
     * `main`'s, so a read in `main` after the call cannot walk to it. Written out, the qualified
     * form degraded to an opaque EXTERNAL node - both reads collapsed onto one, and `bump`'s write
     * reached neither. The type assertion is what catches that; it is paired with the reachability
     * ones, which fail if nothing is connected at all.
     *
     * Ported from codemap's `static_member` and `global_var` fixtures.
     */
    @Test
    fun aStaticFieldIsOneVariableQualifiedOrNot() {
        val graph = buildGraph("staticField", listOf("App.java"))
        val edges = edgeLabels(graph)
        assertTrue("total" to "VARIABLE" in nodeTypes(graph), "the static field is not a variable: $edges")
        assertTrue("total" to "EXTERNAL" !in nodeTypes(graph), "the static field went opaque: ${nodeTypes(graph)}")
        assertTrue(reaches(graph, "5", "before"), "the qualified write does not reach the qualified read: $edges")
        assertTrue(reaches(graph, "5", "after"), "the value before the call does not survive it: $edges")
        assertTrue(reaches(graph, "3", "after"), "the unqualified write inside bump is not seen by main: $edges")
    }

    /**
     * A method leaves by whichever `return` runs, so each one produces the method's value and all
     * of them have to reach the RETURN node. Keeping only the last would draw the guard clauses as
     * dead code - readable, plausible, and claiming the method can only ever return one thing.
     *
     * Ported from codemap's `return` fixture.
     */
    @Test
    fun everyReturnInAMethodProducesItsValue() {
        val edges = edgeLabels(buildGraph("earlyReturn", listOf("App.java")))
        assertTrue("100" to "classify" in edges, "the first guard's return is missing: $edges")
        assertTrue("55" to "classify" in edges, "the second guard's return is missing: $edges")
        assertTrue("*" to "classify" in edges, "the fall-through return is missing: $edges")
        assertTrue("classify" to "result" in edges, "the method's value does not reach the caller: $edges")
    }

    /**
     * A field is declared once, on whichever class in the chain declares it, and a read through a
     * subclass has to find that one. `Leaf` declares neither `fromBase` nor `fromMiddle`, so
     * looking a field up on the receiver's own class would lose both.
     *
     * Ported from codemap's `inheritance` fixture, which used two base classes; Java has one.
     */
    @Test
    fun aFieldDeclaredOnASuperclassIsReadThroughTheSubclass() {
        val graph = buildGraph("inheritance", listOf("App.java"))
        val edges = edgeLabels(graph)
        assertTrue("5" to "fromBase" in edges, "the grandparent's field is not written: $edges")
        assertTrue("10" to "fromMiddle" in edges, "the parent's field is not written: $edges")
        assertTrue("20" to "fromLeaf" in edges, "the subclass's own field is not written: $edges")
        assertTrue(reaches(graph, "5", "total"), "the grandparent's field does not reach the sum: $edges")
        assertTrue(reaches(graph, "10", "total"), "the parent's field does not reach the sum: $edges")
        assertTrue(reaches(graph, "20", "total"), "the subclass's field does not reach the sum: $edges")
    }

    /**
     * Three ways to reach a method declared on a superclass - through `super`, unqualified, and as
     * an inherited static - and all three have a body in the analysed sources, so all three are
     * inlined rather than taking the opaque EXTERNAL path.
     *
     * Ported from codemap's `parent_class_method` fixture.
     */
    @Test
    fun anInheritedMethodIsInlinedHoweverItIsReached() {
        val graph = buildGraph("parentMethod", listOf("App.java"))
        val edges = edgeLabels(graph)
        assertTrue("input" to "amount" in edges, "the argument does not reach super.shift's parameter: $edges")
        assertTrue("amount" to "+" in edges, "super.shift's body was not inlined: $edges")
        assertTrue("offset" to "+" in edges, "the field the parent method reads is missing: $edges")
        // `super.m()` runs on the object the caller is running on, so the field the subclass wrote
        // is the one the parent method reads. Without this the edge above is still drawn, from a
        // fresh `offset` with nothing flowing into it - the same picture, asserting a value that
        // never arrives.
        assertTrue(reaches(graph, "5", "out"), "the subclass's write is not what super.shift reads: $edges")
        assertTrue("shift" to "shifted" in edges, "super.shift does not return its value: $edges")
        assertTrue("shifted" to "factor" in edges, "the argument does not reach the inherited static: $edges")
        assertTrue("factor" to "*" in edges, "the inherited static's body was not inlined: $edges")
        assertTrue("scale" to "scaled" in edges, "the inherited static does not return its value: $edges")
    }

    /**
     * Two names for one object. A write through the alias is a write to the object, so the read
     * after the block finds it - and finds it *instead of* the value written before the block,
     * since one assignment replaced the other rather than adding to it.
     *
     * The negative half is paired with the positive: an implementation that connected nothing
     * would satisfy "1 does not reach read" trivially, and fail the line above it.
     *
     * Ported from codemap's `write_pointed_inside_block` fixture.
     */
    @Test
    fun aWriteThroughAnAliasInANestedBlockIsSeenAfterIt() {
        val graph = buildGraph("aliasInBlock", listOf("App.java"))
        val edges = edgeLabels(graph)
        assertTrue("box" to "alias" in edges, "the alias is not bound to the object: $edges")
        assertTrue(reaches(graph, "7", "read"), "the write through the alias is not seen after the block: $edges")
        assertTrue(!reaches(graph, "1", "read"), "the replaced value still reaches the read: $edges")
    }

    /**
     * A type parameter is a type like any other. The value put in through the constructor is the
     * one the getter returns, whatever `T` was bound to at the call site.
     *
     * Ported from codemap's `template` fixture.
     */
    @Test
    fun aValueFlowsThroughAGenericHolder() {
        val graph = buildGraph("generic", listOf("App.java"))
        val edges = edgeLabels(graph)
        assertTrue("\"payload\"" to "initial" in edges, "the argument does not reach the constructor: $edges")
        assertTrue("initial" to "held" in edges, "the constructor does not write the field: $edges")
        assertTrue("held" to "get" in edges, "the getter does not return the field: $edges")
        assertTrue("get" to "taken" in edges, "the getter's value does not reach the caller: $edges")
        assertTrue(reaches(graph, "\"payload\"", "length"), "flow does not continue past the holder: $edges")
    }

    /**
     * The callee is in another package, in a subdirectory. Resolution is by `Element`, so where a
     * file sits on disk decides nothing about what its names mean.
     *
     * Ported from codemap's `files` fixture, which kept callees under `sub_folder/`.
     */
    @Test
    fun aCalleeInASubdirectoryAndAnotherPackageIsInlined() {
        val edges = edgeLabels(buildGraph("subpackage", listOf("App.java", "util/Adder.java")))
        assertTrue("3" to "left" in edges, "the first argument does not reach the parameter: $edges")
        assertTrue("5" to "right" in edges, "the second argument does not reach the parameter: $edges")
        assertTrue("left" to "+" in edges, "the callee's body was not inlined: $edges")
        assertTrue("add" to "sum" in edges, "the callee's value does not reach the caller: $edges")
    }

    /**
     * `value instanceof String` is a value derived from `value`, and `value instanceof String text`
     * additionally binds `text` to the very same object.
     *
     * Without the binding the graph is not merely missing an edge: every later read of `text` is a
     * name that resolves to nothing, so the whole method fails. With it, the object has to be the
     * one tested, not a new one, or a receiver's fields are looked for in the wrong place.
     */
    @Test
    fun instanceOfTestsAValueAndBindsThePatternToIt() {
        val edges = edgeLabels(buildGraph("instanceOf", listOf("App.java")))
        assertTrue("value" to "instanceof" in edges, "the tested value does not reach the test: $edges")
        assertTrue("instanceof" to "isText" in edges, "the test does not reach the variable: $edges")
        assertTrue("value" to "text" in edges, "the pattern variable is not bound to the tested value: $edges")
        assertTrue("text" to "length" in edges, "the pattern variable is not usable as a receiver: $edges")
    }

    /**
     * Two methods named `twice`, one taking an int and one a String. Which body runs at a call
     * site is decided by the argument types, so a lookup by name has to pick one and be wrong at
     * half the call sites - silently, since the body it inlines is real code that reads fine.
     */
    @Test
    fun overloadsResolveToTheBodyThatRuns() {
        val edges = edgeLabels(buildGraph("overload", listOf("App.java")))
        assertTrue("number" to "value" in edges, "int argument does not reach the int parameter: $edges")
        assertTrue("value" to "*" in edges, "the int overload's body was not inlined: $edges")
        assertTrue("*" to "scaled" in edges, "the int overload's body was not inlined: $edges")
        assertTrue("\"abc\"" to "text" in edges, "String argument does not reach the String parameter: $edges")
        assertTrue("text" to "length" in edges, "the String overload's body was not inlined: $edges")
        assertTrue("length" to "counted" in edges, "the String overload's body was not inlined: $edges")
    }

    /**
     * `Account.close()` and `Connection.close()` are different methods that happen to share a name.
     * Keyed by name they were one entry, so both call sites were drawn with the same body.
     */
    @Test
    fun sameMethodNameOnTwoClassesStaysTwoMethods() {
        val edges = edgeLabels(buildGraph("sameName", listOf("App.java")))
        assertTrue("-" to "settled" in edges, "Account.close's body is missing: $edges")
        assertTrue("+" to "flushed" in edges, "Connection.close's body is missing: $edges")
        assertTrue("settled" to "close" in edges, "Account.close does not return its value: $edges")
        assertTrue("flushed" to "close" in edges, "Connection.close does not return its value: $edges")
    }

    /**
     * `total` names both an int field and a Holder local. Whether a variable holds a value or a
     * reference decides how it is modelled, and reading that off a map keyed by bare name let the
     * last declaration parsed answer for every `total` in the sources.
     */
    @Test
    fun sameNameWithTwoTypesIsModelledByType() {
        val nodes = nodeTypes(buildGraph("shadowedType", listOf("App.java")))
        assertTrue("total" to "OBJ_VARIABLE" in nodes, "the Holder local is not an object: $nodes")
        assertTrue("total" to "VARIABLE" in nodes, "the int field is not a value: $nodes")
    }

    /**
     * The tool is pointed at sources with no classpath, so most of a real file's types cannot be
     * resolved. That has to degrade to the opaque external node, not to a failure and not to a
     * guess - this is the guard on codeflow still working on the input it exists for.
     */
    @Test
    fun unresolvableTypeStaysOpaqueAndTraceable() {
        val edges = edgeLabels(buildGraph("unresolvedType", listOf("App.java")))
        assertTrue("size" to "create" in edges, "argument does not reach the unresolvable call: $edges")
        assertTrue("create" to "widget" in edges, "call result does not reach the variable: $edges")
        assertTrue("widget" to "measure" in edges, "receiver does not reach the call made on it: $edges")
        assertTrue("+" to "total" in edges, "flow does not continue past the unresolvable type: $edges")
    }

    /**
     * outer() and inner() each declare a local `amount` on the same instance. They are two
     * variables, and the value read back in outer() is the one outer() assigned.
     *
     * Keyed by name and instance they were one, and both were filed on the same MemPos under that
     * one key, so the callee's assignment overwrote the caller's and outer() read inner()'s value.
     * The labels cannot tell the two apart, which is the point: on the diagram this was invisible.
     */
    @Test
    fun localsOfTheSameNameInTwoMethodsStayApart() {
        val graph = buildGraph("collidingLocals", listOf("App.java"))
        assertTrue(reaches(graph, "1", "afterwards"), "outer's own value does not reach it: $graph")
        assertTrue(!reaches(graph, "2", "afterwards"), "the callee's value leaked into the caller: $graph")
        assertTrue(reaches(graph, "2", "consumed"), "inner's value does not reach its own read: $graph")
    }

    /**
     * The method boundary is what a viewer draws as a rectangle, so a call has to come out as a
     * node nested inside its caller's node - that containment *is* the boundary in GraphML, there
     * is no separate notion of a group. Flat output would still render, as a correct graph with
     * every method boundary silently gone.
     */
    @Test
    fun graphmlNestsACallInsideItsCaller() {
        val doc = buildGraphml("funcCall", listOf("App.java"))
        val blocks = elements(doc, "node").filter { dataOf(it, "type") == "METHOD" }
        val methodC = blocks.filter { labelOf(it) == "methodC" }
        assertEquals(2, methodC.size, "methodC is inlined at two call sites and should appear twice")
        assertTrue(methodC.all { enclosingBlockLabel(it) == "methodB" }, "methodC is not nested in methodB")

        val methodB = blocks.single { labelOf(it) == "methodB" }
        assertEquals("main", enclosingBlockLabel(methodB), "methodB is not nested in main")

        val paramH = elements(doc, "node").filter { labelOf(it) == "paramH" }
        assertTrue(paramH.isNotEmpty(), "methodC's parameter is missing")
        assertTrue(paramH.all { enclosingBlockLabel(it) == "methodC" }, "a node escaped its own method")
    }

    /**
     * `<init>`, `<`, `>` and a quoted literal are all real labels, and all of them are XML syntax.
     * Written raw they produce a document a viewer refuses to open, or worse, one it opens with the
     * label truncated at the first bad character.
     */
    @Test
    fun graphmlEscapesLabelsThatAreXmlSyntax() {
        val constructor = elements(buildGraphml("constructor", listOf("App.java")), "node").map { labelOf(it) }
        assertTrue("<init>" in constructor, "the constructor's return label did not survive: $constructor")
        assertTrue("\"test\"" in constructor, "the string literal's label did not survive: $constructor")

        val operators = elements(buildGraphml("operators", listOf("App.java")), "node").map { labelOf(it) }
        assertTrue("<" in operators, "the less-than operator did not survive: $operators")
        assertTrue(">=" in operators, "the greater-or-equal operator did not survive: $operators")
    }

    /**
     * The two exporters render one graph, so they have to agree on it. The risk is specific: an
     * edge can cross a method boundary - a return flows to the variable in the caller - and GraphML
     * requires such an edge to be declared in a graph enclosing both ends, unlike Mermaid, which
     * takes it anywhere. Getting that wrong drops exactly the edges that join methods together.
     */
    @Test
    fun graphmlKeepsEveryEdgeTheMermaidGraphHas() {
        val mermaid = edgeLabels(buildGraph("funcCall", listOf("App.java"))).sortedBy { it.toString() }
        val graphml = graphmlEdgeLabels(buildGraphml("funcCall", listOf("App.java"))).sortedBy { it.toString() }
        assertEquals(mermaid, graphml, "the two renderings of one graph disagree on its edges")
    }

    /**
     * `parent` is what Cytoscape draws as a containing box, so it is the method boundary and
     * nothing else carries it. A payload with the nesting flattened renders as a correct graph
     * with every boundary silently gone.
     */
    @Test
    fun jsonNestsACallInsideItsCaller() {
        val doc = buildJson("funcCall", listOf("App.java"))
        val nodes = jsonNodes(doc)
        val byId = nodes.associateBy { it.get("id").asString }

        val root = nodes.single { jsonParent(it) == null }
        assertEquals("main", jsonLabel(root), "the parentless node should be the outermost method")

        val methodC = nodes.filter { jsonLabel(it) == "methodC" && it.get("type").asString == "METHOD" }
        assertEquals(2, methodC.size, "methodC is inlined at two call sites and should appear twice")
        assertTrue(
            methodC.all { jsonLabel(byId.getValue(jsonParent(it)!!)) == "methodB" },
            "methodC is not nested in methodB"
        )

        val paramH = nodes.filter { jsonLabel(it) == "paramH" }
        assertTrue(paramH.isNotEmpty(), "methodC's parameter is missing")
        assertTrue(
            paramH.all { jsonLabel(byId.getValue(jsonParent(it)!!)) == "methodC" },
            "a node escaped its own method"
        )
    }

    /**
     * A label carrying a quote ends the JSON string early and the rest of the payload becomes
     * syntax errors, so the page renders nothing at all.
     */
    @Test
    fun jsonEscapesLabelsThatAreJsonSyntax() {
        val labels = jsonNodes(buildJson("constructor", listOf("App.java"))).map { jsonLabel(it) }
        assertTrue("\"test\"" in labels, "the string literal's label did not survive: $labels")
        assertTrue("<init>" in labels, "the constructor's return label did not survive: $labels")
    }

    /** The three exporters render one graph, so they have to agree on its edges. */
    @Test
    fun jsonKeepsEveryEdgeTheMermaidGraphHas() {
        val mermaid = edgeLabels(buildGraph("funcCall", listOf("App.java"))).sortedBy { it.toString() }
        val json = jsonEdgeLabels(buildJson("funcCall", listOf("App.java"))).sortedBy { it.toString() }
        assertEquals(mermaid, json, "the two renderings of one graph disagree on its edges")
    }

    /**
     * The page has to carry its own libraries. A viewer that renders nothing because an asset was
     * missing looks exactly like a graph with no nodes, so the export fails loudly instead.
     */
    @Test
    fun htmlPageCarriesItsLibrariesAndItsData() {
        val page = StringBuilder()
        val testDirPath = testResourcesPath.resolve("funcCall")
        val mainMethod = AstReader(testResourcesPath).process(listOf(testDirPath.resolve("App.java")))
        HtmlExporter().processMainMethod(mainMethod) { page.append(it).append("\n") }
        val html = page.toString()

        // Strings from inside the bundles themselves. "cytoscape" and "ELK" both occur in our own
        // viewer.mjs, so asserting on those passed with not one library present.
        assertTrue("The Cytoscape Consortium" in html, "the renderer was not inlined")
        assertTrue("org.eclipse.elk" in html, "the layout engine was not inlined")
        assertTrue("REVEAL_DEPTH" in html, "our own viewer code was not inlined")
        assertTrue("\"label\": \"methodC\"" in html, "the graph payload was not inlined")
        assertTrue("<script" in html && "</html>" in html, "the page is not a complete document")
    }

